package workbook.member; import java.sql.*;import java.util.*;import workbook.common.DBConnection; public class MemberDAO {
public List<Member> findAll() throws SQLException{List<Member> a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT member_id,name,phone,email FROM member ORDER BY member_id");ResultSet r=p.executeQuery()){while(r.next())a.add(new Member(r.getString(1),r.getString(2),r.getString(3),r.getString(4)));}return a;}
public int insert(Member m)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO member VALUES(?,?,?,?)")){p.setString(1,m.memberId());p.setString(2,m.name());p.setString(3,m.phone());p.setString(4,m.email());return p.executeUpdate();}}
public int update(Member m)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE member SET name=?,phone=?,email=? WHERE member_id=?")){p.setString(1,m.name());p.setString(2,m.phone());p.setString(3,m.email());p.setString(4,m.memberId());return p.executeUpdate();}}
public int delete(String id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM member WHERE member_id=?")){p.setString(1,id);return p.executeUpdate();}}}